// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    RevertingActor actor;

    function setUp() public { c = new ReentrancyDAO(); actor = new RevertingActor(c); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint256).max / 2);
        vm.deal(address(actor), amount);
        actor.deposit(amount);
        bool ok = true;
        try actor.withdraw() { ok = true; } catch { ok = false; }
        assertTrue(ok == false, "withdrawAll must revert when the outgoing transfer fails");
    }
}

contract RevertingActor {
    ReentrancyDAO c;
    constructor(ReentrancyDAO c_) { c = c_; }
    function deposit(uint256 amt) external payable { c.deposit{value: amt}(); }
    function withdraw() external { c.withdrawAll(); }
    fallback() external payable { revert(); }
}
